// Источник: web-тест .qa/e2e/tests/important-dates/id-01-add-window-by-type.spec.ts, план .qa/e2e/specs/important-dates.md (17.1), кейс .qa/tests/important-dates/ID-01-type-title-fields-a11y.md
// Тикет #6a86f7e0. Опора: AC2/AC3; реджекты 22.09, 23.09; Figma 454:11002.
// @data: создаёт אזכרה «QA-AUTO-נפטר»; в finally удаляются ВСЕ записи «QA-AUTO-…».
import { $$, driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith, byText, byTextContains, tapLabel, tapText, expectVisibleText, swipeUp } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { isoDate } from '../../../e2e/tests/_helpers/dates.ts';

const editButtons = () => (driver.isAndroid
  ? $$('android=new UiSelector().descriptionMatches(".*QA-AUTO-.*: פתיחה לעריכה")').getElements()
  : $$('-ios predicate string:name MATCHES ".*QA-AUTO-.*: פתיחה לעריכה"').getElements());

/** «בית» → прокрутить до «הוספת תאריך חשוב». */
async function homeDates() {
  await goTab('בית');
  const add = await byLabel('הוספת תאריך חשוב');
  for (let i = 0; i < 8 && !(await add.isDisplayed().catch(() => false)); i++) await swipeUp();
  await add.waitForDisplayed({ timeout: 20000 });
}
/** Уборка: удалить любые «QA-AUTO-…». */
async function deleteQaDates() {
  await toHome();
  await homeDates();
  for (let guard = 0; guard < 10; guard++) {
    const list = await editButtons();
    if (list.length === 0) break;
    await list[0].click();
    await tapText('מחיקת התאריך');
    await tapText('מחיקה');
    await driver.waitUntil(async () => (await editButtons()).length < list.length, { timeout: 15000 });
  }
}

describe('Важные даты и אזכרות', () => {
  afterEach(async () => { await toHome(); });

  it('ID-01 Окно «+» по типу — заголовок «תאריך חדש» / «אזכרה», поля по типу; у сохранённой אזכרה видно имя и a11y-имя правки #6a86f7e0 #00542c25 @data', async () => {
    try {
      // 1. «בית» → «הוספת תאריך חשוב» → меню «תאריך חשוב» / «אזכרה».
      await homeDates();
      await tapLabel('הוספת תאריך חשוב');
      await expectVisibleText('תאריך חשוב');
      await expectVisibleText('אזכרה');

      // 2. «תאריך חשוב»: одно поле «שם התאריך», нет «אחרי השקיעה»; закрыть «סגירה».
      await tapText('תאריך חשוב');
      // Заголовок окна новой даты — «תאריך חדש» (#00542c25, עבר QA 21.10; Figma S-29 454:9416). Чип на главной остаётся «תאריך חשוב».
      await expect(byText('תאריך חדש')).toBeDisplayed({ wait: 10000 });
      await expect(byLabel('שם התאריך')).toBeDisplayed();
      await expect(byLabel('שם הנפטר')).not.toBeDisplayed();
      await expect(byTextContains('אחרי השקיעה')).not.toBeDisplayed();
      await tapLabel('סגירה');
      await expect(byLabel('שם התאריך')).not.toBeDisplayed();

      // 3. «אזכרה»: поле «שם הנפטר», checkbox «אחרי השקיעה»; «הוסף תאריך» неактивна без имени и дня.
      await tapLabel('הוספת תאריך חשוב');
      await tapText('אזכרה');
      const deceased = await byLabel('שם הנפטר');
      await deceased.waitForDisplayed();
      await expect(byLabel('הפטירה הייתה אחרי השקיעה')).toBeDisplayed();
      await expect(byText('הוסף תאריך')).toBeDisabled();
      await deceased.setValue('QA-AUTO-נפטר');
      await expect(byText('הוסף תאריך')).toBeDisabled();
      // Первый день текущего месяца — всегда не в будущем.
      const now = new Date();
      await (await byLabelStartsWith(`${isoDate(new Date(now.getFullYear(), now.getMonth(), 1, 12))}, `)).click();
      await expect(byText('הוסף תאריך')).toBeEnabled();
      await tapText('הוסף תאריך');
      await expect(byLabel('שם הנפטר')).not.toBeDisplayed();

      // 4. Запись в «תאריכים חשובים»: «אזכרה», имя, «האזכרה הבאה:», «סדר אזכרה»; a11y-имена правки и סדר אזכרה.
      const open = await byLabel('אזכרה, QA-AUTO-נפטר: פתיחת סדר האזכרה');
      for (let i = 0; i < 6 && !(await open.isDisplayed().catch(() => false)); i++) await swipeUp();
      await open.waitForDisplayed({ timeout: 20000 });
      await expect(byLabel('אזכרה, QA-AUTO-נפטר: פתיחה לעריכה')).toBeExisting();
      await expect(byTextContains('QA-AUTO-נפטר')).toBeDisplayed();
      await expect(byTextContains('האזכרה הבאה:')).toBeDisplayed();
      await expect(byTextContains('סדר אזכרה')).toBeDisplayed();
    } finally {
      // 5. Уборка → записи «QA-AUTO-נפטר» нет.
      await deleteQaDates();
      await expect(byTextContains('QA-AUTO-נפטר')).not.toBeDisplayed();
    }
  });
});
